package com.mohymods.kingdomsmp.profession;
import java.util.*;
import net.minecraft.nbt.*;
/** One bounded saved boundary for real planting/growth/harvest, never retrospective crop inference. */
public final class ReagentCropProof {
 public record Cell(String dimension,long position){public Cell{if(net.minecraft.resources.ResourceLocation.tryParse(dimension)==null)throw new IllegalArgumentException("Invalid crop dimension");}}
 public record Plant(UUID owner,int age){public Plant{Objects.requireNonNull(owner);if(age<0||age>7)throw new IllegalArgumentException("Invalid native crop age");}}
 private final Map<Cell,Plant> plants=new HashMap<>();private final Map<UUID,Integer> counts=new HashMap<>();
 public void plant(Cell cell,UUID player){if(plants.containsKey(cell)||plants.size()<8192)plants.put(cell,new Plant(player,0));}
 public void invalidate(Cell cell){plants.remove(cell);}
 public void grow(Cell cell,int before,int after){var old=plants.get(cell);if(old==null)return;if(old.age()==after&&after>before)return;if(old.age()!=before||after<=before||after>7){plants.remove(cell);return;}plants.put(cell,new Plant(old.owner(),after));}
 public Optional<Plant> take(Cell cell){return Optional.ofNullable(plants.remove(cell));}
 public int count(UUID owner){return counts.getOrDefault(owner,0);}
 public void harvest(UUID owner,int amount){if(amount<1||amount>128)throw new IllegalArgumentException("Invalid native reagent drop count");if(!counts.containsKey(owner)&&counts.size()>=128)throw new IllegalStateException("Reagent player bound exceeded");counts.put(owner,Math.min(1000000,Math.addExact(count(owner),amount)));}
 public CompoundTag save(){var root=new CompoundTag();root.putInt("schema",1);var rows=new ListTag();plants.forEach((cell,p)->{var row=new CompoundTag();row.putString("dimension",cell.dimension());row.putLong("position",cell.position());row.putUUID("owner",p.owner());row.putInt("age",p.age());rows.add(row);});root.put("plants",rows);var totals=new CompoundTag();counts.forEach((id,n)->totals.putInt(id.toString(),n));root.put("counts",totals);return root;}
 public static ReagentCropProof load(CompoundTag tag){if(!tag.getAllKeys().equals(Set.of("schema","plants","counts"))||!tag.contains("schema",Tag.TAG_INT)||tag.getInt("schema")!=1||!tag.contains("plants",Tag.TAG_LIST)||!tag.contains("counts",Tag.TAG_COMPOUND))throw new IllegalArgumentException("Invalid reagent provenance schema");var result=new ReagentCropProof();var rows=tag.getList("plants",Tag.TAG_COMPOUND);if(rows.size()>8192||((ListTag)tag.get("plants")).size()!=rows.size())throw new IllegalArgumentException("Invalid crop proof rows");for(var value:rows){var row=(CompoundTag)value;if(!row.getAllKeys().equals(Set.of("dimension","position","owner","age"))||!row.contains("dimension",Tag.TAG_STRING)||!row.contains("position",Tag.TAG_LONG)||!row.hasUUID("owner")||!row.contains("age",Tag.TAG_INT))throw new IllegalArgumentException("Malformed crop proof");var cell=new Cell(row.getString("dimension"),row.getLong("position"));if(result.plants.put(cell,new Plant(row.getUUID("owner"),row.getInt("age")))!=null)throw new IllegalArgumentException("Duplicate crop cell");}var totals=tag.getCompound("counts");if(totals.size()>128)throw new IllegalArgumentException("Too many reagent players");for(var id:totals.getAllKeys()){if(!totals.contains(id,Tag.TAG_INT)||totals.getInt(id)<1||totals.getInt(id)>1000000)throw new IllegalArgumentException("Invalid reagent count");if(result.counts.put(UUID.fromString(id),totals.getInt(id))!=null)throw new IllegalArgumentException("Duplicate reagent player identity");}return result;}
}
